// ============================================================
//  main.ts — Ponto de entrada da aplicação (roda na CPU)
// ------------------------------------------------------------
//  Responsabilidades nesta FASE 1:
//    - obter o <canvas>;
//    - inicializar o WebGPU (GPUContext);
//    - criar o Renderer;
//    - rodar o game loop com requestAnimationFrame.
//
//  A separação update(dt) / render() já é preparada aqui, mesmo
//  que na FASE 1 não haja lógica de jogo para atualizar ainda.
// ============================================================

import { GPUContext } from "./gpu/GPUContext";
import { Renderer } from "./renderer/Renderer";
import * as mat4 from "./core/math/mat4";

// Exibe uma mensagem de erro em tela cheia (ex.: WebGPU indisponível).
function showFatal(message: string): void {
  const el = document.getElementById("fatal");
  if (el) {
    el.textContent = message;
    el.classList.remove("hidden");
  }
  console.error(message);
}

async function boot(): Promise<void> {
  const canvas = document.getElementById("gpu-canvas") as HTMLCanvasElement | null;
  if (!canvas) {
    showFatal("Canvas #gpu-canvas não encontrado no HTML.");
    return;
  }

  let gpu: GPUContext;
  try {
    // Inicializa adapter, device e contexto do canvas.
    gpu = await GPUContext.create(canvas);
  } catch (err) {
    showFatal(err instanceof Error ? err.message : String(err));
    return;
  }

  // Ajusta o framebuffer ao tamanho da janela agora e a cada resize.
  gpu.resize();
  window.addEventListener("resize", () => gpu.resize());

  const renderer = new Renderer(gpu);

  // ---------------------------------------------------------
  //  GAME LOOP
  //  update(dt): lógica de jogo — na FASE 2, apenas gira o cubo.
  //  render():   calcula a MVP (CPU) e desenha o frame (GPU).
  // ---------------------------------------------------------
  let lastTime = performance.now();
  let cubeAngle = 0; // ângulo de rotação acumulado (radianos)

  // Câmera fixa nesta fase (a câmera FPS controlável vem na FASE 3).
  const eye: [number, number, number] = [0, 1.2, 3.2];
  const target: [number, number, number] = [0, 0, 0];
  const up: [number, number, number] = [0, 1, 0];

  function frame(now: number): void {
    const dt = (now - lastTime) / 1000; // delta em segundos
    lastTime = now;

    update(dt);

    // --- Monta a matriz MVP (na CPU); a GPU a aplica por vértice. ---
    // Model: gira o cubo nos eixos Y e X.
    const model = mat4.multiply(mat4.rotationY(cubeAngle), mat4.rotationX(cubeAngle * 0.5));
    // View: câmera olhando para a origem.
    const view = mat4.lookAt(eye, target, up);
    // Projection: perspectiva usando o aspect ratio atual do canvas.
    const aspect = gpu.canvas.width / gpu.canvas.height;
    const proj = mat4.perspective((60 * Math.PI) / 180, aspect, 0.1, 100);
    // MVP = Projection * View * Model.
    const mvp = mat4.chain(proj, view, model);

    renderer.render(mvp);

    requestAnimationFrame(frame);
  }

  function update(dt: number): void {
    // Gira o cubo ~45°/s. Lógica de jogo real chega nas próximas fases.
    cubeAngle += dt * 0.8;
  }

  requestAnimationFrame(frame);
  console.info("[Jogo GPU] FASE 2 ok — cubo 3D com MVP renderizado pela GPU.");
}

boot();

