// ============================================================
//  cube.ts — Geometria de um cubo (dados na CPU)
// ------------------------------------------------------------
//  Define os dados que serão enviados à GPU para desenhar um cubo.
//
//  Usamos VÉRTICES + ÍNDICES (index buffer):
//    - 8 vértices únicos (os 8 cantos do cubo);
//    - 36 índices (6 faces × 2 triângulos × 3 vértices) que
//      reutilizam esses 8 vértices.
//  Isso evita repetir posições e é a base do "indexed drawing".
//
//  Layout de cada vértice: posição (x,y,z) + cor (r,g,b) = 6 floats.
//  Damos a cada canto uma cor distinta só para visualizar as faces
//  em 3D nesta fase (iluminação de verdade vem na FASE 15).
// ============================================================

export const CUBE_FLOATS_PER_VERTEX = 6;

// 8 cantos de um cubo centrado na origem, lado 1 (de -0.5 a 0.5).
// prettier-ignore
export const CUBE_VERTICES = new Float32Array([
  // x,    y,    z,     r,   g,   b
  -0.5, -0.5, -0.5,   0.9, 0.2, 0.2, // 0
   0.5, -0.5, -0.5,   0.2, 0.9, 0.2, // 1
   0.5,  0.5, -0.5,   0.2, 0.4, 0.9, // 2
  -0.5,  0.5, -0.5,   0.9, 0.9, 0.2, // 3
  -0.5, -0.5,  0.5,   0.9, 0.2, 0.9, // 4
   0.5, -0.5,  0.5,   0.2, 0.9, 0.9, // 5
   0.5,  0.5,  0.5,   0.95, 0.6, 0.2, // 6
  -0.5,  0.5,  0.5,   0.7, 0.7, 0.9, // 7
]);

// 36 índices. Winding no sentido anti-horário visto de fora
// (combina com o "front face" padrão do WebGPU: counter-clockwise).
// prettier-ignore
export const CUBE_INDICES = new Uint16Array([
  // face traseira (-z)
  0, 2, 1,  0, 3, 2,
  // face frontal (+z)
  4, 5, 6,  4, 6, 7,
  // face esquerda (-x)
  0, 4, 7,  0, 7, 3,
  // face direita (+x)
  1, 2, 6,  1, 6, 5,
  // face inferior (-y)
  0, 1, 5,  0, 5, 4,
  // face superior (+y)
  3, 7, 6,  3, 6, 2,
]);

