// ============================================================
//  GPUContext — Camada de inicialização do WebGPU (roda na CPU)
// ------------------------------------------------------------
//  Responsabilidade única: obter e guardar os objetos base do
//  WebGPU e configurar o canvas. NÃO desenha nada — apenas prepara
//  o "hardware" para o Renderer usar.
//
//  Objetos WebGPU inicializados aqui:
//    - GPUAdapter        → representa uma GPU física disponível.
//    - GPUDevice         → interface lógica para enviar comandos à GPU.
//    - GPUCanvasContext  → liga o <canvas> à GPU (destino do render).
//    - formato de textura preferido do canvas.
// ============================================================

export class GPUContext {
  readonly adapter: GPUAdapter;
  readonly device: GPUDevice;
  readonly context: GPUCanvasContext;
  readonly canvas: HTMLCanvasElement;
  readonly format: GPUTextureFormat;

  private constructor(
    adapter: GPUAdapter,
    device: GPUDevice,
    context: GPUCanvasContext,
    canvas: HTMLCanvasElement,
    format: GPUTextureFormat,
  ) {
    this.adapter = adapter;
    this.device = device;
    this.context = context;
    this.canvas = canvas;
    this.format = format;
  }

  // Fábrica assíncrona: toda a negociação com a GPU é assíncrona,
  // por isso não pode ficar no construtor.
  static async create(canvas: HTMLCanvasElement): Promise<GPUContext> {
    // 1) O navegador expõe WebGPU em navigator.gpu.
    if (!navigator.gpu) {
      throw new Error(
        "WebGPU não está disponível neste navegador.\n" +
          "Use Chrome/Edge 113+ ou Firefox recente com WebGPU habilitado.",
      );
    }

    // 2) Pede um adaptador (uma GPU física). Preferimos alta performance.
    const adapter = await navigator.gpu.requestAdapter({
      powerPreference: "high-performance",
    });
    if (!adapter) {
      throw new Error("Nenhum GPUAdapter encontrado (navigator.gpu.requestAdapter retornou null).");
    }

    // 3) Pede um device: a interface lógica pela qual enviamos comandos.
    const device = await adapter.requestDevice();

    // Se o device for perdido (ex.: driver reiniciou), avisamos no console.
    device.lost.then((info) => {
      console.error(`GPUDevice perdido: ${info.reason ?? "desconhecido"} — ${info.message}`);
    });

    // 4) Obtém o contexto WebGPU do canvas — destino final do render.
    const context = canvas.getContext("webgpu");
    if (!context) {
      throw new Error("Não foi possível obter o contexto 'webgpu' do canvas.");
    }

    // 5) Formato de textura preferido do sistema (ex.: bgra8unorm).
    //    Usar o formato preferido evita conversões e melhora performance.
    const format = navigator.gpu.getPreferredCanvasFormat();

    // 6) Configura o context: associa device + formato ao canvas.
    context.configure({
      device,
      format,
      alphaMode: "opaque",
    });

    return new GPUContext(adapter, device, context, canvas, format);
  }

  // Ajusta o tamanho do framebuffer ao tamanho real em pixels do canvas,
  // considerando telas HiDPI (devicePixelRatio). Deve ser chamado no início
  // e sempre que a janela for redimensionada.
  resize(): void {
    const dpr = window.devicePixelRatio || 1;
    const width = Math.max(1, Math.floor(this.canvas.clientWidth * dpr));
    const height = Math.max(1, Math.floor(this.canvas.clientHeight * dpr));

    if (this.canvas.width !== width || this.canvas.height !== height) {
      this.canvas.width = width;
      this.canvas.height = height;
    }
  }
}

src/renderer/Renderer.ts:
// ============================================================
//  Renderer — Desenha a cena usando WebGPU
// ------------------------------------------------------------
//  FASE 2: desenha um CUBO 3D indexado, transformado por uma
//  matriz MVP na GPU, com teste de profundidade (depth buffer).
//
//  Novidades desta fase em relação à FASE 1:
//    - Vertex + Index buffer (desenho indexado).
//    - Uniform buffer com a matriz MVP.
//    - Bind group (liga o uniform buffer ao shader).
//    - Depth texture + depth test (para faces próximas ocluírem
//      as distantes corretamente).
//    - Face culling (não desenha faces de trás).
//
//  Divisão CPU x GPU:
//    CPU: monta geometria/matriz, cria buffers, grava comandos.
//    GPU: multiplica cada vértice pela MVP (vertex shader),
//         faz depth test, rasteriza e colore (fragment shader).
// ============================================================

import { GPUContext } from "../gpu/GPUContext";
import { Mat4 } from "../core/math/mat4";
import { CUBE_VERTICES, CUBE_INDICES, CUBE_FLOATS_PER_VERTEX } from "../geometry/cube";
import cubeVertSrc from "../shaders/cube.vert.wgsl?raw";
import cubeFragSrc from "../shaders/cube.frag.wgsl?raw";

const VERTEX_STRIDE_BYTES = CUBE_FLOATS_PER_VERTEX * Float32Array.BYTES_PER_ELEMENT; // 24 bytes
const DEPTH_FORMAT: GPUTextureFormat = "depth24plus";
const UNIFORM_SIZE_BYTES = 16 * Float32Array.BYTES_PER_ELEMENT; // uma mat4x4<f32> = 64 bytes

export class Renderer {
  private readonly gpu: GPUContext;
  private readonly pipeline: GPURenderPipeline;
  private readonly vertexBuffer: GPUBuffer;
  private readonly indexBuffer: GPUBuffer;
  private readonly indexCount: number;
  private readonly uniformBuffer: GPUBuffer;
  private readonly bindGroup: GPUBindGroup;

  // Depth texture recriada quando o tamanho do canvas muda.
  private depthTexture: GPUTexture | null = null;
  private depthView: GPUTextureView | null = null;
  private depthWidth = 0;
  private depthHeight = 0;

  constructor(gpu: GPUContext) {
    this.gpu = gpu;
    const { device, format } = gpu;

    // ---- 1) Vertex buffer (posições + cores dos 8 cantos) ----
    this.vertexBuffer = device.createBuffer({
      label: "cube-vertices",
      size: CUBE_VERTICES.byteLength,
      usage: GPUBufferUsage.VERTEX | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(this.vertexBuffer, 0, CUBE_VERTICES);

    // ---- 2) Index buffer (36 índices formando 12 triângulos) ----
    this.indexCount = CUBE_INDICES.length;
    this.indexBuffer = device.createBuffer({
      label: "cube-indices",
      size: CUBE_INDICES.byteLength,
      usage: GPUBufferUsage.INDEX | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(this.indexBuffer, 0, CUBE_INDICES);

    // ---- 3) Uniform buffer (guarda a matriz MVP, atualizada por frame) ----
    this.uniformBuffer = device.createBuffer({
      label: "cube-uniforms(mvp)",
      size: UNIFORM_SIZE_BYTES,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    });

    // ---- 4) Shaders ----
    const vertexModule = device.createShaderModule({ label: "cube.vert", code: cubeVertSrc });
    const fragmentModule = device.createShaderModule({ label: "cube.frag", code: cubeFragSrc });

    // ---- 5) Layout do vertex buffer (casa com @location do shader) ----
    const vertexBufferLayout: GPUVertexBufferLayout = {
      arrayStride: VERTEX_STRIDE_BYTES,
      attributes: [
        { shaderLocation: 0, offset: 0, format: "float32x3" }, // position
        { shaderLocation: 1, offset: 3 * 4, format: "float32x3" }, // color
      ],
    };

    // ---- 6) Render pipeline ----
    this.pipeline = device.createRenderPipeline({
      label: "cube-pipeline",
      layout: "auto",
      vertex: {
        module: vertexModule,
        entryPoint: "main",
        buffers: [vertexBufferLayout],
      },
      fragment: {
        module: fragmentModule,
        entryPoint: "main",
        targets: [{ format }],
      },
      primitive: {
        topology: "triangle-list",
        cullMode: "back", // descarta faces traseiras (otimização + correção)
        frontFace: "ccw", // frente = winding anti-horário
      },
      // Habilita o teste de profundidade usando a depth texture.
      depthStencil: {
        format: DEPTH_FORMAT,
        depthWriteEnabled: true,
        depthCompare: "less", // fragmento mais próximo (menor z) vence
      },
    });

    // ---- 7) Bind group: liga o uniform buffer ao binding 0 do shader ----
    this.bindGroup = device.createBindGroup({
      label: "cube-bind-group",
      layout: this.pipeline.getBindGroupLayout(0),
      entries: [{ binding: 0, resource: { buffer: this.uniformBuffer } }],
    });
  }

  // (Re)cria a depth texture caso o tamanho do canvas tenha mudado.
  private ensureDepthTexture(): GPUTextureView {
    const { device, canvas } = this.gpu;
    const w = canvas.width;
    const h = canvas.height;

    if (!this.depthTexture || this.depthWidth !== w || this.depthHeight !== h) {
      this.depthTexture?.destroy();
      this.depthTexture = device.createTexture({
        label: "depth-texture",
        size: [w, h],
        format: DEPTH_FORMAT,
        usage: GPUTextureUsage.RENDER_ATTACHMENT,
      });
      this.depthView = this.depthTexture.createView();
      this.depthWidth = w;
      this.depthHeight = h;
    }
    return this.depthView!;
  }

  // Desenha um frame. Recebe a matriz MVP já calculada na CPU.
  render(mvp: Mat4): void {
    const { device, context } = this.gpu;

    // Envia a MVP deste frame para a GPU (uniform buffer).
    device.queue.writeBuffer(this.uniformBuffer, 0, mvp);

    const depthView = this.ensureDepthTexture();
    const encoder = device.createCommandEncoder({ label: "frame-encoder" });
    const colorView = context.getCurrentTexture().createView();

    const pass = encoder.beginRenderPass({
      label: "cube-pass",
      colorAttachments: [
        {
          view: colorView,
          clearValue: { r: 0.04, g: 0.04, b: 0.06, a: 1.0 },
          loadOp: "clear",
          storeOp: "store",
        },
      ],
      // Anexo de profundidade: limpa para 1.0 (mais distante possível).
      depthStencilAttachment: {
        view: depthView,
        depthClearValue: 1.0,
        depthLoadOp: "clear",
        depthStoreOp: "store",
      },
    });

    pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bindGroup);
    pass.setVertexBuffer(0, this.vertexBuffer);
    pass.setIndexBuffer(this.indexBuffer, "uint16");
    pass.drawIndexed(this.indexCount);
    pass.end();

    device.queue.submit([encoder.finish()]);
  }
}

